entries[171244] = { ["name"] = "Anhänger: Ahm", ["text"] = "Sofort\nAhm wurde von dem grausamen Orc Klingenmeister Bralok gefangen genommen, als dieser sein Heimatdorf angriff. Während seiner Gefangenschaft quälte der Orc ihn mit Schlägen und Essensentzug, aber dennoch beugte sich Ahm nicht seinem Willen. Im Tode macht er weiterhin Jagd auf die Eiserne Horde, um Rache für ihre Grausamkeiten zu nehmen." }
