entries[171250] = { ["name"] = "Schriftrolle der Geschwindigkeit", ["text"] = "Sofort 5 min Abklingzeit\nErhöht 8 Sek. lang Eure und die Bewegungsgeschwindigkeit aller verbündeten Ziele in der Nähe um 70%. Spielercharaktere können nicht mehr als eine Schriftrolle der Geschwindigkeit gleichzeitig aktivieren." }
