entries[171611] = { ["name"] = "Entzugsritual", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde entzieht den Kreaturen der Höhle ihre Lebenskraft. Jeder dieser Geister, der den Zaubernden erreicht, heilt den Zaubernden um 2% seiner maximalen Gesundheit. Alle Spielercharaktere, die diese Geister unterbrechen, erleiden Schattenschaden." }
entries[171612] = { ["name"] = "Kriechende Seele", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde entzieht den Kreaturen der Höhle ihre Lebenskraft. Jeder dieser Geister, der den Zaubernden erreicht, heilt den Zaubernden um 2% seiner maximalen Gesundheit. Alle Spielercharaktere, die diese Geister unterbrechen, erleiden Schattenschaden." }
entries[171613] = { ["name"] = "Infernototem", ["text"] = "100 Meter Reichweite\nSofort\nBeschwört ein feuriges Infernototem." }
entries[171614] = { ["name"] = "Inferno", ["text"] = "Wirken in 5 sek.\nFügt allen Gegnern im Umkreis von 45 Metern 87 Feuerschaden zu." }
entries[171615] = { ["name"] = "Herrliches Feuerwerk", ["text"] = "Sofort\nEntfesselt die Kraft der Liebe." }
entries[171616] = { ["name"] = "Dorrhautklippentrampler", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Dorrhautklippentrampler oder gibt ihn wieder frei.\n\"Bei dieser Grollhufart sind die Hufe mit kleinen Kerben bedeckt, was es ihr erleichtert, ungefährdet Bergregionen auf der Suche nach Nahrung zu erklimmen.\"\nVerkäufer:\nHändlerin Araanda\nZone:\nMondsturz\nKosten:\n20000\n\nVerkäufer:\nHändler Darakk\nZone:\nFrostwall\nKosten:\n20000\n\n|" }
entries[171617] = { ["name"] = "Zugerittener Eishuf", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren zugerittenen Eishuf oder gibt ihn wieder frei.\n\"Bevor Euch dieses Reittier gehörte, hattet Ihr ja nicht die geringste Ahnung davon, wie schwer es in Draenor werden würde. Grollhufhaare überall!\"\nHerkunft:\nStall der Garnison" }
entries[171618] = { ["name"] = "Alte Lederhaut", ["text"] = "Wirken in 1.5 sek.\nBeschwört Eure alte Lederhaut oder gibt sie wieder frei." }
entries[171619] = { ["name"] = "Tundraeishuf", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Tundraeishuf oder gibt ihn wieder frei.\n\"Das durchscheinende Unterfell dieser Art ist eine perfekte Isolierung für den Einsatz in kalten Umgebungen.\"\nBeute von:\nRache, Todeskralle, Terrorfaust, Verdammniswalze\nZone:\nTanaandschungel" }
entries[171620] = { ["name"] = "Bluthufbulle", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Bluthufbullen oder gibt ihn wieder frei.\n\"Schon lange jagen die Mitglieder des Kriegshymnenklans diese Grollhufe, um ihre blutrote Haut für Schlachtstandarten zu verwenden.\"\nBeute von:\nNakk der Donnerer\nOrt:\nNagrand" }
entries[171621] = { ["name"] = "Eisenhufzerstörer", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Eisenhufzerstörer oder gibt ihn wieder frei.\n\"Es wird behauptet, dass Schwarzfaust die feurige Rüstung für die Schlachtgrollhufe der Eisernen Horde selbst entworfen hat.\"\nBeute von:\nSchwarzfaust\nOrt:\nSchwarzfelsgießerei (Mythisch)" }
entries[171622] = { ["name"] = "Scheckiger Wiesentrampler", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren scheckigen Wiesentrampler oder gibt ihn wieder frei.\n\"Mit seinem langen Rüssel kann dieser Elekk Nahrung erschnüffeln, Gefahren umgehen und Leckerlis aus Eurer Tasche stibitzen, wenn Ihr gerade nicht hinseht.\"\nBeute von:\nLuk'hok\nZone:\nNagrand" }
entries[171623] = { ["name"] = "Zugerittener Wiesentrampler", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren zugerittenen Wiesentrampler oder gibt ihn wieder frei.\n\"Die Draenei haben schon vor langer Zeit die Elekkhaltung perfektioniert und schmücken die Kreaturen mit lichtgetränkten Kristallen, um sie gefügig zu machen.\"\nQuest:\nStall der Garnison" }
entries[171624] = { ["name"] = "Schattenfellperlzahn", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Schattenfellperlzahn oder gibt ihn wieder frei.\n\"Einigen Legenden zufolge haben die Draenei sich mit den Elekks angefreundet, nachdem eines dieser wilden Tiere einen verletzten Späher vor einem Rudel bösartiger Schotlinge beschützt hatte.\"\nBeute von:\nZurückgelassener Invasorenschatz" }
entries[171625] = { ["name"] = "Staubige Steinhaut", ["text"] = "Wirken in 1.5 sek.\nBeschwört Eure staubige Steinhaut oder gibt sie wieder frei.\n\"Seit Ihr dieses Reittier erworben habt, habt Ihr merkwürdige Fieberträume von einer Parade tanzender und trötender rosa Elekks. Elekks hin, Elekks her, in rosa, da stör'n sie Euch sehr!\"\nVerkäufer:\nVerteidiger Nuurem\nExarchenrat - Ehrfürchtig\nOrt:\nSturmschild\nKosten:\n5.000\n+ 5.000" }
entries[171626] = { ["name"] = "Gepanzerter Eisenzahn", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren gepanzerten Eisenzahn oder gibt ihn wieder frei.\n\"Es wird behauptet, dass ein Elekk nie etwas vergisst. Es ist also kein Wunder, dass dieses Tier die Eiserne Horde verachtet, wenn man bedenkt, was für Qualen die Orcs ihm angetan haben.\"\nVerkäufer:\n\nSha'tarverteidigung - Ehrfürchtig\nOrt:\nGarnison - Handelsposten\nKosten:\n5.000\n+ 5.000" }
entries[171627] = { ["name"] = "Schwarzstahlkampfeber", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Schwarzstahlkampfeber oder gibt ihn wieder frei.\n\"Weigert sich zu rennen, wenn sein Schädel nicht mit schweren Metallstacheln bedeckt ist. Das stärkt sein Ego.\"\nErfolg:\nRuhm des Draenorschlachtzüglers" }
entries[171628] = { ["name"] = "Felshauerkampfeber", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Schwarzstahlkampfeber oder gibt ihn wieder frei.\n\"Angelockt werden potenzielle Partner nicht etwa durch den Metallhelm, sondern durch den fetzigen Irokesenschnitt.\"\nVerkäufer:\nHändlerin Araanda\nZone:\nMondsturz\nKosten:\n10000\n\nVerkäufer:\nHändler Darakk\nZone:\nFrostwall\nKosten:\n10000\n\n|" }
entries[171629] = { ["name"] = "Gepanzerter Frosteber", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren gepanzerten Frosteber oder gibt ihn wieder frei.\n\"Ernährt sich praktisch ausschließlich von gefrorenen Beeren. Gibt sich jedoch auch mit dem Geschmack von langsamen Fremdlingen zufrieden.\"\nErfolg:\nFortgeschrittene Viehhaltung" }
entries[171630] = { ["name"] = "Gepanzerter Klingenrücken", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren gepanzerten Klingenrücken oder gibt ihn wieder frei.\n\"Passt bloß auf, dass er... NIEMALS... Schinken in Eurer Tasche riecht.\"\nBeute von:\nRache, Todeskralle, Terrorfaust, Verdammniswalze\nZone:\nTanaandschungel" }
entries[171631] = { ["name"] = "Achievement Credit", ["text"] = "Sofort\nGestattet es Euch, in Eurer Garnison Gildenbanner aufzustellen." }
entries[171632] = { ["name"] = "Frostebenenkampfeber", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Frostebenenkampfeber oder gibt ihn wieder frei.\n\"Ohne dieses coole Hauerpiercing würde er sich in dem Outfit echt bekloppt vorkommen.\"\nErfolg:\nRuhm des Draenorhelden" }
entries[171633] = { ["name"] = "Wilder Geiferzahn", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren wilden Geiferzahn oder gibt ihn wieder frei.\n\"Wenn Ihr gemütlich reiten möchtet, sucht Euch doch einen \"zahmen Glückshauer\" oder so.\"\nVerkäufer:\nZ'tenga der Wanderer\nZone:\nTanaandschungel\nDie Säbelzahnpirscher - Wohlwollend\nKosten:\n1.000" }
entries[171634] = { ["name"] = "Domestizierter Klingenrücken", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren domestizierten Klingenrücken oder gibt ihn wieder frei.\n\"Domestiziert\" heißt nicht \"freundlich\". Bringt also Leckerlis mit.\nVerkäufer:\nGazrix Kolbenfresser/Mimi Wirbelwolke\nWerterhaltungsgesellschaft des Dampfdruckkartells - Ehrfürchtig\nOrt:\nSturmschild/Kriegsspeer\nKosten:\n5.000\n+ 5.000" }
entries[171635] = { ["name"] = "Riesige Kaltschnauze", ["text"] = "Wirken in 1.5 sek.\nBeschwört Eure riesige Kaltschnauze oder gibt sie wieder frei.\n\"Die Schnauze ist nicht nur kalt, sondern auch nass. Es gibt angenehmere Methoden, aufgeweckt zu werden.\"\nBeute von:\nZurückgelassener Invasorenschatz" }
entries[171636] = { ["name"] = "Mächtiger Grauhauer", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren mächtigen Grauhauer oder gibt ihn wieder frei.\n\"Wirft seine Hauer einmal im Jahr ab und ist äußert schüchtern, bis sie nachgewachsen sind.\"\nBeute von:\nGorok\nZone:\nFrostfeuergrat" }
entries[171637] = { ["name"] = "Zugerittener Felshauer", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren zugerittenen Felshauer oder gibt ihn wieder frei.\n\"Gründlich darin ausgebildet, wie man schnaubt, trötet und auf den Gesichtern seiner Feinde herumtrampelt.\"\nQuest:\nStall der Garnison" }
entries[171638] = { ["name"] = "Zugerittener Flussfläzer", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren zugerittenen Flussfläzer oder gibt ihn wieder frei.\n\"Flussfläzer gehören zu den kräftigsten Tieren in Draenor, was ihnen mehr Ausdauer und eine markante Färbung verleiht.\"\nQuest:\nStall der Garnison" }
