entries[171690] = { ["name"] = "Echtstahlbarren", ["text"] = "Wirken in 1.5 sek. 1 tag Abklingzeit\nTools: Schmiedehammer\nReagenzien:\nEchteisenerz (20), Schwarzfelserz (10)\nProduziert 8 (plus zusätzliche, je nach Schmiedefertigkeit).\n\nKann auch magisches Feuer und/oder magische Erde erzeugen.\n\nDie Abklingzeit wird täglich abgeschlossen.\nVerkäufer:\nAuria Erzträumer\nGegenstand:\nSchmiedekunst von Draenor\nKosten:\n100\nZone:\nMondsturz\n\nVerkäufer:\nRoyce Großbart\nGegenstand:\nSchmiedekunst von Draenor\nKosten:\n100\nZone:\nAshran\n\nEchtstahlbarren\nWird beim Aufheben gebunden\nHandwerksmaterial" }
entries[171691] = { ["name"] = "Qualmender Helm", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nSchwarzfelserz (60)\nOptionale Reagenzien:\n[] (#31)\nVerkäufer:\nAuria Erzträumer\nGegenstand:\nSchmiedekunst von Draenor\nKosten:\n100\nZone:\nMondsturz\n\nVerkäufer:\nRoyce Großbart\nGegenstand:\nSchmiedekunst von Draenor\nKosten:\n100\nZone:\nAshran\n\nQualmender Helm\nWird beim Anlegen gebunden\nKopf Platte\n13 Rüstung\n+4 [Stärke oder Intelligenz]+7 Ausdauer\nHaltbarkeit 85 / 85\n39" }
