entries[171824] = { ["name"] = "Saphirblaue Flussbestie", ["text"] = "Wirken in 1.5 sek.\nBeschwört Eure saphirblaue Flussbestie oder gibt sie wieder frei.\n\"Die Farbe des Tiers ähnelt dem klaren Blau der Flüsse Draenors und macht es für Raubtiere im Wasser nahezu unsichtbar.\"\nBeute von:\nSchlickhaut\nZone:\nTalador" }
entries[171825] = { ["name"] = "Mooshautflussfläzer", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Mooshautflussfläzer oder gibt ihn wieder frei.\n\"Die Mooshaut verteidigt ihr Gebiet aggressiv und versteckt sich häufig im Buschwerk an Flüssen, um ahnungslose Passanten zu attackieren.\"\nVerkäufer:\nDämmerungssucher Krek / Dämmerungssucher Alkset\nOrt:\nSturmschild/Kriegsspeer\nKosten:\n50.000\n+ 5.000" }
entries[171826] = { ["name"] = "Schlammrückenflussbestie", ["text"] = "Wirken in 1.5 sek.\nBeschwört Eure Schlammrückenflussbestie oder gibt sie wieder frei.\n\"Ein spezielles Gewebe an den Fußsohlen des Schlammrückens gewährt ihm zusätzlichen Halt in Schlamm und auf rutschigen Untergründen.\"\nGarnisonsmission:\nIst es ein Schiff? Ist es ein Flugzeug? Nein, nur eine Flussbestie!" }
entries[171827] = { ["name"] = "Höllenfeuerbestie", ["text"] = "Wirken in 1.5 sek.\nBeschwört Eure Höllenfeuerbestie oder gibt sie wieder frei.\n\"Aus den Tiefen des Nethers wird eine Kreatur heraufbeschworen, die aus purem Hass besteht und danach trachtet, alles Leben auf ihrem Wege auszulöschen.\"\nBeute von:\nGul'dan (Mythisch)\nZone:\nDie Nachtfestung" }
entries[171828] = { ["name"] = "Sonnenfalke der Spitzen", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Sonnenfalken der Spitzen oder gibt ihn wieder frei.\n\"Wenn man in die Augen dieses mystischen Wesens blickt, hat man das Gefühl, man würde in das Herz der Sonne starren. Beim Reiten ist das Tragen einer Schutzbrille anzuraten.\"\nBeute von:\nRukhmar" }
entries[171829] = { ["name"] = "Schattenmähnenstürmer", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Schattenmähnenstürmer oder gibt ihn wieder frei.\n\"Draeneidichter bezeichnen die Farbe dieses Talbuks als Schatten des Mondlichts im aschgrauen Wald.\"\nVerkäufer:\nRabensprecher Skeega / Schattenweiser Brakoss\nAusgestoßene Arakkoa - Ehrfürchtig\nOrt:\nSturmschild/Kriegsspeer\nKosten:\n5.000\n+ 5.000" }
entries[171830] = { ["name"] = "Flinker Brisenschreiter", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren flinken Brisenschreiter oder gibt ihn wieder frei.\n\"Die Draenei haben dieses Reittier, das schnellste aller Talbuks, mit der Aufgabe betraut, ihre Boten und Nachrichten sicher an ihre Ziele zu bringen.\"\nBeute von:\nPfadläufer\nZone:\nSchattenmondtal" }
entries[171831] = { ["name"] = "Zugerittenes Silberfell", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euer zugerittenes Silberfell oder gibt es wieder frei.\n\"Dieser Talbuk ist aufgrund seiner Intelligenz beliebt und wird darauf trainiert, im Kampf zu treten und Gegner aufzuspießen.\"\nOrt:\nStall der Garnison" }
entries[171832] = { ["name"] = "Brisenschreiterhengst", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Brisenschreiterhengst oder gibt ihn wieder frei.\n\"Die rote Färbung des Brisenschreiters spiegelt sein Temperament wider: lebhaft, stürmisch und tapfer.\"\nVerkäufer:\nDazzerian\nVol'jins Speer - Ehrfürchtig\nOrt:\nKriegsspeer\nKosten:\n5.000\n+ 5.000" }
entries[171833] = { ["name"] = "Heller Dornzehrer", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren hellen Dornzehrer oder gibt ihn wieder frei.\n\"Dieser Talbuk ernährt sich ausschließlich von Disteln und Dornen, weshalb sein Inneres genauso widerstandsfähig ist, wie sein Äußeres.\"\nVerkäufer:\nMagor Geistbeuger\nWrynns Vorhut - Ehrfürchtig\nOrt:\nSturmschild\nKosten:\n5.000\n+ 5.000" }
entries[171834] = { ["name"] = "Boshafter Kriegswidder", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren boshaften Kriegswidder oder gibt ihn wieder frei.\n\"Bevor er Eure empfindlichsten Körperregionen nicht mit seinem Kopf rammt, hat er Euch nicht wirklich als seinen Reiter akzeptiert.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1" }
entries[171835] = { ["name"] = "Boshafter Kriegsraptor", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren boshaften Kriegsraptor oder gibt ihn wieder frei.\n\"Weil scharfe Zähne und Klauen einfach nicht ausreichen.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1" }
entries[171836] = { ["name"] = "Stahlzahngarn", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Stahlzahngarn oder gibt ihn wieder frei.\n\"Ein Trainer versuchte einst, das Maul des Stahlrachenwolfs mit Metalldekorationen zu verschönern. Drei Tage hat es gedauert, bis er sein Material zurückhatte.\"\nBeute von:\nZurückgelassener Invasorenschatz" }
entries[171837] = { ["name"] = "Terrorzahn des Kriegshymnenklans", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Terrorzahn des Kriegshymnenklans oder gibt ihn wieder frei.\n\"Dieses Tier hat einen eisernen Willen, doch wenn Ihr ihm einen Grollhufknochen zum Zerkauen bringt, ist es ganz lieb.\"\nBeute von:\nRache, Todeskralle, Terrorfaust, Verdammniswalze\nZone:\nTanaandschungel" }
entries[171838] = { ["name"] = "Gepanzerter Frostwolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren gepanzerten Frostwolf oder gibt ihn wieder frei.\n\"Er ist dazu ausgebildet, das harsche Wetter des Frostfeuergrats zu überleben, also kuschelt er, als würde sein Leben davon abhängen.\"\nErfolg:\nStallmeister" }
entries[171839] = { ["name"] = "Eisenflankenkriegswolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Eisenflankenkriegswolf oder gibt ihn wieder frei.\n\"An seinem Schwanz hängt ein gepanzerter Stachel. Wenn Ihr seinen Bauch unbedingt kraulen wollt, tut Ihr es auf eigene Gefahr.\"\nVerkäufer:\nHau'tot\nLachender Schädel - Ehrfürchtig\nOrt:\nGarnison - Handelsposten (Horde)\nKosten:\n5.000\n+ 5.000" }
entries[171840] = { ["name"] = "Kaltflammenhöllenbestie", ["text"] = "Wirken in 1.5 sek.\nBeschwört Eure Kaltflammenhöllenbestie oder gibt sie wieder frei.\n\"Die eigenartigen, eisigen Flammen lassen Euch gleichzeitig schwitzen und frieren.\"\nHandelsposten" }
entries[171841] = { ["name"] = "Zugerittener Knurrer", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren zugerittenen Knurrer oder gibt ihn wieder frei.\n\"Als Welpe unheimlich süß. Jetzt nicht mehr so sehr.\"\nQuest:\nStall der Garnison" }
entries[171842] = { ["name"] = "Schneller Frostwolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren schnellen Frostwolf oder gibt ihn wieder frei.\n\"In den kalten Höhen des Frostfeuergrats jagen die Frostwölfe allem nach, was sie fangen können. Die Schnellsten von ihnen bekommen reichlich zu beißen.\"\nVerkäufer:\nBeska Rothauer\nFrostwolforcs - Ehrfürchtig\nOrt:\nKriegsspeer\nKosten:\n5.000\n+ 5.000" }
entries[171843] = { ["name"] = "Rauchgrauer Terrorwolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren rauchgrauen Terrorwolf oder gibt ihn wieder frei.\n\"Man vermutet, dass sie größtenteils im Norden hausen. Können Hochzeiten absolut nicht leiden.\"\nBeute von:\nZurückgelassener Invasorenschatz" }
entries[171844] = { ["name"] = "Staubmähnenterrorwolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Staubmähnenterrorwolf oder gibt ihn wieder frei.\n\"Staubmähnen sind verglichen mit anderen Terrorwölfen eher zurückhaltend. Damit sie sich als Reittiere verdingen, müssen Sie mit etwas überzeugt werden, das für sie etwas Besonderes darstellt.\"\nBeruf:\nLederverarbeitung" }
entries[171845] = { ["name"] = "Todesrad des Kriegsherrn", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euer Todesrad des Kriegsherrn oder gibt es wieder frei.\n\"Dieses brüllende Ungetüm wird häufig als \"Goblinrasenmäher\" bezeichnet, da dieses knurrende Monstrum Feinde behandelt, als wären sie aus Gras... das bereit ist, gemäht zu werden.\"\nErfolg:\nKategorie:\nHeldentaten" }
entries[171846] = { ["name"] = "Kettenrad des Champions", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euer Kettenrad des Champions oder gibt es wieder frei.\n\"Menschen, Gnome und Zwerge haben gemeinsam dieses gepanzerte Meisterstück geschaffen, das einen Tauren im Handumdrehen in mundgerechte Stücke zerteilt.\"\nVerkäufer:\nPaulie\nZone:\nSturmwind, Altstadt\nKosten:\n100000" }
entries[171847] = { ["name"] = "Glutmähnenschlachtross", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euer Glutmähnenschlachtross oder gibt es wieder frei.\n\"Von Ragnaros persönlich als Geschenk für die Tochter erschaffen, die er nie hatte.\"\nWerbt einen Freund" }
entries[171848] = { ["name"] = "Kriegsyeti des Herausforderers", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Kriegsyeti des Herausforderers oder gibt ihn wieder frei.\n\"Glücklicherweise bewegen sie sich schnell und hinterlassen nur den Geruch.\"\nErfolg:\nHerausforderungskriegsherr: Silber" }
entries[171849] = { ["name"] = "Sonnenhautgronnling", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Sonnenhautgronnling oder gibt ihn wieder frei.\n\"Liebt die Sonne und hasst alles andere.\"\nBeute von:\nRammfaust\nZone:\nGorgrond" }
entries[171850] = { ["name"] = "Llothienstreuner", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Llothienstreuner oder gibt ihn wieder frei.\n\"Diese geschmeidigen Füchse können trotz ihrer Größe geräuschlos über frisch gefallene Blätter streifen.\"\nQuest:\nDer scheue Volpin\nZone:\nSuramar" }
entries[171851] = { ["name"] = "Nachtheuler der Garn", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euren Nachtheuler der Garn oder gibt ihn wieder frei.\n\"Die Garn gehören zu den gefährlichsten Raubtieren in Draenor und jagen immer im Rudel.\"\nBeute von:\nNok-Karosh\nOrt:\nFrostfeuergrat" }
