entries[171892] = { ["name"] = "Schreddernetz", ["text"] = "35 Meter Reichweite\nWirken in 1.5 sek. 3 sek. Abklingzeit\nFängt den Gegner in einem Netz und fügt ihm beim Treffer körperlichen Schaden sowie danach alle 1 Sek. körperlichem Schaden zu. Außerdem wird das Ziel 4 Sek. lang bewegungsunfähig gemacht." }
entries[171893] = { ["name"] = "Seelendieb", ["text"] = "20 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nEntzieht einem Gegner im Verlauf von 5 Sek. Gesundheit und überträgt sie auf den Zaubernden." }
